import React, { useState, useEffect } from 'react';
import { Menu, X, Phone, ShieldCheck } from 'lucide-react';

interface NavbarProps {
  onAdminClick: () => void;
  onHomeClick: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onAdminClick, onHomeClick }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Início', href: '#inicio' },
    { name: 'Empresa', href: '#empresa' },
    { name: 'Produtos', href: '#produtos' },
    { name: 'Parceiros', href: '#parceiros' },
    { name: 'Contato', href: '#contato' },
  ];

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-pindorama-green shadow-lg py-3' : 'bg-transparent py-5'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <div 
            className="flex items-center cursor-pointer group"
            onClick={onHomeClick}
          >
            <div className="bg-white p-2 rounded-lg mr-3 group-hover:bg-amber-100 transition-colors">
              <ShieldCheck className="text-pindorama-green w-8 h-8" />
            </div>
            <div>
              <span className="text-white text-2xl font-bold tracking-tight block leading-none">PINDORAMA</span>
              <span className="text-amber-400 text-xs font-semibold tracking-[0.2em] uppercase">Madeireira • Uberaba</span>
            </div>
          </div>

          <div className="hidden md:flex items-center space-x-8">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                className="text-white/90 hover:text-amber-400 font-medium text-sm transition-colors uppercase tracking-wider"
              >
                {link.name}
              </a>
            ))}
            <button
              onClick={onAdminClick}
              className="bg-amber-600 hover:bg-amber-700 text-white px-5 py-2 rounded-full text-sm font-bold transition-transform hover:scale-105"
            >
              Área Administrativa
            </button>
          </div>

          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-white hover:text-amber-400 focus:outline-none"
            >
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-pindorama-green border-t border-white/10 px-2 pt-2 pb-3 space-y-1 sm:px-3">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="block px-3 py-2 text-white hover:bg-white/10 rounded-md text-base font-medium"
              onClick={() => setIsOpen(false)}
            >
              {link.name}
            </a>
          ))}
          <button
            onClick={() => {
              onAdminClick();
              setIsOpen(false);
            }}
            className="w-full text-left px-3 py-2 text-amber-400 font-bold"
          >
            Área Administrativa
          </button>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { HERO_IMAGES } from '../constants';
import { ChevronLeft, ChevronRight } from 'lucide-react';

const Hero: React.FC = () => {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrent((prev) => (prev + 1) % HERO_IMAGES.length);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

  const next = () => setCurrent((prev) => (prev + 1) % HERO_IMAGES.length);
  const prev = () => setCurrent((prev) => (prev === 0 ? HERO_IMAGES.length - 1 : prev - 1));

  return (
    <section id="inicio" className="relative h-screen w-full overflow-hidden">
      {HERO_IMAGES.map((img, index) => (
        <div
          key={img}
          className={`absolute inset-0 transition-opacity duration-[1500ms] ease-in-out ${index === current ? 'opacity-100 scale-105' : 'opacity-0 scale-100'}`}
          style={{ transitionProperty: 'opacity, transform' }}
        >
          <div className="absolute inset-0 bg-black/50 z-10" />
          <img
            src={img}
            alt="Hero Background"
            className="w-full h-full object-cover"
          />
        </div>
      ))}

      <div className="relative z-20 h-full flex items-center justify-center text-center px-4">
        <div className="max-w-4xl">
          <h2 className="text-amber-400 text-lg md:text-xl font-semibold mb-4 tracking-widest uppercase animate-fade-in-down">
            Desde 1979 em Uberaba
          </h2>
          <h1 className="text-white text-5xl md:text-7xl font-bold mb-8 drop-shadow-lg leading-tight">
            Madeireira Pindorama: <br />
            <span className="text-amber-50">Solidez e Tradição</span>
          </h1>
          <p className="text-white/80 text-lg md:text-xl mb-10 max-w-2xl mx-auto font-light leading-relaxed">
            Fornecendo as melhores madeiras para construção, móveis e acabamentos com o compromisso de quem conhece o ofício há mais de 45 anos.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a
              href="#produtos"
              className="bg-pindorama-green text-white px-8 py-4 rounded-full font-bold text-lg hover:bg-green-900 transition-all shadow-xl hover:-translate-y-1"
            >
              Ver Nossos Produtos
            </a>
            <a
              href="#contato"
              className="bg-white/10 backdrop-blur-md border border-white/20 text-white px-8 py-4 rounded-full font-bold text-lg hover:bg-white/20 transition-all shadow-xl hover:-translate-y-1"
            >
              Falar com Vendedor
            </a>
          </div>
        </div>
      </div>

      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-30 flex gap-2">
        {HERO_IMAGES.map((_, i) => (
          <button
            key={i}
            onClick={() => setCurrent(i)}
            className={`w-3 h-3 rounded-full transition-all ${i === current ? 'bg-amber-400 w-8' : 'bg-white/30'}`}
          />
        ))}
      </div>

      <button
        onClick={prev}
        className="absolute left-6 top-1/2 -translate-y-1/2 z-30 p-3 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full text-white transition-all hidden md:block"
      >
        <ChevronLeft size={32} />
      </button>
      <button
        onClick={next}
        className="absolute right-6 top-1/2 -translate-y-1/2 z-30 p-3 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full text-white transition-all hidden md:block"
      >
        <ChevronRight size={32} />
      </button>
    </section>
  );
};

export default Hero;

