    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00'
  });

  const [messages, setMessages] = useState([
    { id: '1', name: 'João da Silva', content: 'Solicitação de orçamento para telhado colonial.', time: 'Há 15 minutos' },
    { id: '2', name: 'Maria Lúcia', content: 'Dúvida sobre entrega em cidades vizinhas.', time: 'Há 30 minutos' },
    { id: '3', name: 'Paulo Costa', content: 'Interesse em deck de Cumaru para piscina.', time: 'Há 1 hora' }
  ]);

  const handleDeleteProduct = (id: string) => {
