                  <button onClick={() => handleDeleteBanner(idx)} className="bg-red-500 text-white p-3 rounded-full hover:bg-red-600 transition-colors">
                    <Trash2 size={24} />
                  </button>
                </div>
                <div className="p-4 text-center font-bold text-stone-400">Banner #{idx + 1}</div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'partners' && (
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
            {partners.map((p) => (
              <div key={p.id} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200 text-center relative group">
                <img src={p.logo} alt={p.name} className="h-16 w-auto object-contain mx-auto mb-4" />
                <p className="font-bold text-black text-sm uppercase">{p.name}</p>
                <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => setEditingPartner(p)} className="p-1 bg-white text-stone-400 hover:text-amber-600 rounded"><Edit2 size={14} /></button>
                  <button onClick={() => handleDeletePartner(p.id)} className="p-1 bg-white text-stone-400 hover:text-red-500 rounded"><Trash2 size={14} /></button>
                </div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'messages' && (
          <div className="space-y-4">
            {messages.map((m) => (
              <div key={m.id} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200 flex justify-between items-center">
                <div className="flex gap-4 items-center">
                  <div className="w-10 h-10 bg-amber-100 text-amber-800 rounded-full flex items-center justify-center font-bold">{m.name.charAt(0)}</div>
                  <div>
                    <h4 className="font-bold text-black">{m.name}</h4>
                    <p className="text-stone-500 text-sm">{m.content}</p>
                  </div>
                </div>
                <button onClick={() => onDeleteMessage(m.id)} className="text-stone-300 hover:text-red-500"><Trash2 size={20} /></button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-2xl bg-white p-8 rounded-2xl shadow-sm border border-stone-200">
            <form onSubmit={(e) => { e.preventDefault(); onUpdateSettings(localSettings); alert('Configurações salvas!'); }} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-stone-400 uppercase">Nome da Empresa</label>
                  <input type="text" className="w-full px-4 py-2 rounded-lg border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500" value={localSettings.siteName} onChange={(e) => setLocalSettings({...localSettings, siteName: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-stone-400 uppercase">WhatsApp</label>
                  <input type="text" className="w-full px-4 py-2 rounded-lg border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500" value={localSettings.whatsapp} onChange={(e) => setLocalSettings({...localSettings, whatsapp: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-stone-400 uppercase">Endereço</label>
                <input type="text" className="w-full px-4 py-2 rounded-lg border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500" value={localSettings.address} onChange={(e) => setLocalSettings({...localSettings, address: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-pindorama-green text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2"><Save size={20} /> Salvar Tudo</button>
            </form>
          </div>
        )}

        {/* Modal Produto */}
        {editingProduct && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl overflow-hidden">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingProduct.id.startsWith('new-') ? 'Novo Produto' : 'Editar Produto'}</h3>
                <button onClick={() => setEditingProduct(null)}><X size={24} /></button>
              </div>
              <form onSubmit={handleSaveProduct} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome do Produto</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500 outline-none" placeholder="Ex: Viga de Ipê" value={editingProduct.name} onChange={(e) => setEditingProduct({...editingProduct, name: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Categoria</label>
                    <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500 outline-none" value={editingProduct.category} onChange={(e) => setEditingProduct({...editingProduct, category: e.target.value})}>
                      {CATEGORIES.filter(c => c.id !== 'all').map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Preço</label>
                    <input type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500 outline-none" placeholder="Ex: R$ 50,00/m" value={editingProduct.price || ''} onChange={(e) => setEditingProduct({...editingProduct, price: e.target.value})} />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Descrição</label>
                  <textarea className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500 outline-none h-24 resize-none" value={editingProduct.description} onChange={(e) => setEditingProduct({...editingProduct, description: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Foto do Produto</label>
                  <div className="flex items-center gap-4">
                    {editingProduct.image && <img src={editingProduct.image} className="w-16 h-16 rounded-lg object-cover border border-stone-200" />}
                    <input type="file" accept="image/*" className="hidden" id="prod-img" onChange={(e) => handleImageUpload(e, (url) => setEditingProduct({...editingProduct, image: url}))} />
                    <label htmlFor="prod-img" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold">
                      Clique para fazer upload
                    </label>
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingProduct(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg hover:bg-green-900 transition-all">Salvar Alterações</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modal Parceiro */}
        {editingPartner && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingPartner.id.startsWith('new-') ? 'Novo Parceiro' : 'Editar Parceiro'}</h3>
                <button onClick={() => setEditingPartner(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => { 
                e.preventDefault(); 
                const newList = editingPartner.id.startsWith('new-') ? [...partners, {...editingPartner, id: Date.now().toString()}] : partners.map(p => p.id === editingPartner.id ? editingPartner : p);
                onUpdatePartners(newList);
                setEditingPartner(null);
              }} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Marca/Empresa</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black focus:ring-2 focus:ring-amber-500 outline-none" value={editingPartner.name} onChange={(e) => setEditingPartner({...editingPartner, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Logo (Upload)</label>
                  <div className="flex items-center gap-4">
                    {editingPartner.logo && <img src={editingPartner.logo} className="w-16 h-16 rounded-lg object-contain bg-stone-50 border border-stone-200 p-2" />}
                    <input type="file" accept="image/*" className="hidden" id="partner-img" onChange={(e) => handleImageUpload(e, (url) => setEditingPartner({...editingPartner, logo: url}))} />
                    <label htmlFor="partner-img" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold">Upload da Logo</label>
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingPartner(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg">Salvar Parceiro</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPanel;

