import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS } from './constants';
import { Product, Partner, SiteSettings } from './types';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [banners, setBanners] = useState<string[]>(HERO_IMAGES);
  const [partners, setPartners] = useState<Partner[]>(PARTNERS);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'PINDORAMA',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const [messages, setMessages] = useState([
    { id: '1', name: 'João da Silva', content: 'Solicitação de orçamento para telhado colonial.', time: 'Há 15 minutos' },
    { id: '2', name: 'Maria Lúcia', content: 'Dúvida sobre entrega em cidades vizinhas.', time: 'Há 30 minutos' },
    { id: '3', name: 'Paulo Costa', content: 'Interesse em deck de Cumaru para piscina.', time: 'Há 1 hora' }
  ]);

  // Simulação de injeção de scripts de rastreamento
  useEffect(() => {
    if (settings.googleTag) {
      console.log(`Injetando Google Tag: ${settings.googleTag}`);
    }
    if (settings.pixelId) {
      console.log(`Injetando Facebook Pixel: ${settings.pixelId}`);
    }
  }, [settings.googleTag, settings.pixelId]);

  const handleDeleteProduct = (id: string) => {
    if (window.confirm('Tem certeza absoluta que deseja excluir este produto?')) {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setProducts(products.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const handleAddProduct = (newProduct: Product) => {
    setProducts([...products, { ...newProduct, id: Date.now().toString() }]);
  };

  const handleDeleteMessage = (id: string) => {
    if (window.confirm('Deseja excluir esta mensagem permanentemente?')) {
      setMessages(messages.filter(m => m.id !== id));
    }
  };

  const handleUpdateBanners = (newBanners: string[]) => {
    setBanners(newBanners);
  };

  const handleUpdatePartners = (newPartners: Partner[]) => {
    setPartners(newPartners);
  };

  if (isAdmin) {
    return (
      <AdminPanel 
        products={products}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        messages={messages}
        onDeleteMessage={handleDeleteMessage}
        settings={settings}
        onUpdateSettings={setSettings}
        banners={banners}
        onUpdateBanners={handleUpdateBanners}
        partners={partners}
        onUpdatePartners={handleUpdatePartners}
        onLogout={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} 
      />
      <main>
        <Hero images={banners} />
        <About />
        <Partners partners={partners} />
        <Products products={products} />
        <Testimonials />
      </main>
      <Footer settings={settings} />

      <a
        href={`https://wa.me/${settings.whatsapp}`}
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-8 right-8 z-40 bg-green-500 text-white p-4 rounded-full shadow-2xl hover:bg-green-600 transition-all hover:scale-110 flex items-center justify-center"
      >
        <svg viewBox="0 0 24 24" width="32" height="32" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" /></svg>
      </a>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { LayoutDashboard, Package, MessageSquare, Settings, LogOut, Plus, Trash2, Edit2, TrendingUp, Users, Save, X, Image as ImageIcon, Briefcase, Instagram, Facebook, Tag, Code } from 'lucide-react';
import { Product, Partner, SiteSettings } from '../types';
import { CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  messages: any[];
  onDeleteMessage: (id: string) => void;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => void;
  banners: string[];
  onUpdateBanners: (banners: string[]) => void;
  partners: Partner[];
  onUpdatePartners: (partners: Partner[]) => void;
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, onDeleteProduct, onUpdateProduct, onAddProduct,
  messages, onDeleteMessage,
  settings, onUpdateSettings,
  banners, onUpdateBanners,
  partners, onUpdatePartners,
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(settings);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        callback(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      if (editingProduct.id.startsWith('new-')) {
        onAddProduct(editingProduct);
      } else {
        onUpdateProduct(editingProduct);
      }
      setEditingProduct(null);
    }
  };

  const handleDeleteBanner = (index: number) => {
    if (window.confirm('Tem certeza que deseja remover esta imagem do banner inicial?')) {
      const newBanners = [...banners];
      newBanners.splice(index, 1);
      onUpdateBanners(newBanners);
    }
  };

  const handleDeletePartner = (id: string) => {
    if (window.confirm('Tem certeza que deseja remover este parceiro/marca?')) {
      onUpdatePartners(partners.filter(p => p.id !== id));
    }
  };

  const handleDeleteMsg = (id: string) => {
    onDeleteMessage(id);
  };

  const stats = [
    { label: 'Total de Produtos', value: products.length, icon: <Package className="text-amber-600" /> },
    { label: 'Marcas Parceiras', value: partners.length, icon: <Briefcase className="text-amber-600" /> },
    { label: 'Banners Ativos', value: banners.length, icon: <ImageIcon className="text-amber-600" /> },
    { label: 'Mensagens', value: messages.length, icon: <MessageSquare className="text-amber-600" /> },
  ];

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-pindorama-green text-white flex flex-col shrink-0">
        <div className="p-8 border-b border-white/10">
          <h2 className="text-2xl font-bold tracking-tight uppercase">PAINEL ADM</h2>
          <p className="text-xs text-amber-400 font-bold tracking-widest mt-1 uppercase">Madeireira Pindorama</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'dashboard' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <LayoutDashboard size={20} /> Dashboard
          </button>
          <button onClick={() => setActiveTab('products')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'products' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <Package size={20} /> Produtos
          </button>
          <button onClick={() => setActiveTab('banners')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'banners' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <ImageIcon size={20} /> Banners
          </button>
          <button onClick={() => setActiveTab('partners')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'partners' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <Briefcase size={20} /> Parceiros & Marcas
          </button>
          <button onClick={() => setActiveTab('messages')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'messages' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <MessageSquare size={20} /> Mensagens
          </button>
          <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'settings' ? 'bg-amber-600' : 'hover:bg-white/5'}`}>
            <Settings size={20} /> Configurações
          </button>
        </nav>

        <button onClick={onLogout} className="m-4 flex items-center gap-3 px-4 py-3 rounded-lg text-red-400 hover:bg-red-400/10 transition-colors font-bold">
          <LogOut size={20} /> Sair do Painel
        </button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-8 relative">
        <header className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-pindorama-green capitalize">
            {activeTab === 'dashboard' ? 'Resumo' : activeTab === 'products' ? 'Produtos' : activeTab === 'banners' ? 'Banner Inicial' : activeTab === 'partners' ? 'Parceiros' : activeTab === 'messages' ? 'Mensagens' : 'Ajustes'}
          </h1>
          <div className="flex gap-2">
            {activeTab === 'products' && (
              <button onClick={() => setEditingProduct({ id: `new-${Date.now()}`, name: '', description: '', category: 'bruto', subcategory: '', image: '', price: '' })} className="bg-amber-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-amber-700 shadow-md">
                <Plus size={18} /> Novo Produto
              </button>
            )}
            {activeTab === 'banners' && (
              <div className="relative">
                <input type="file" className="hidden" id="banner-upload" accept="image/*" onChange={(e) => handleImageUpload(e, (url) => onUpdateBanners([...banners, url]))} />
                <label htmlFor="banner-upload" className="bg-amber-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-amber-700 shadow-md cursor-pointer">
                  <Plus size={18} /> Adicionar Banner
                </label>
              </div>
            )}
            {activeTab === 'partners' && (
              <button onClick={() => setEditingPartner({ id: `new-${Date.now()}`, name: '', logo: '' })} className="bg-amber-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-amber-700 shadow-md">
                <Plus size={18} /> Novo Parceiro
              </button>
            )}
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {stats.map((s) => (
              <div key={s.label} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200">
                <div className="bg-amber-50 w-12 h-12 rounded-xl flex items-center justify-center mb-4">{s.icon}</div>
                <p className="text-stone-500 text-sm font-medium">{s.label}</p>
                <p className="text-3xl font-bold text-pindorama-green">{s.value}</p>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'products' && (
          <div className="bg-white rounded-2xl shadow-sm border border-stone-200 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-stone-50 border-b border-stone-200">
                <tr>
                  <th className="px-6 py-4 font-bold text-stone-600">Produto</th>
                  <th className="px-6 py-4 font-bold text-stone-600">Categoria / Sub</th>
                  <th className="px-6 py-4 font-bold text-stone-600 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-stone-100">
                {products.map((p) => (
                  <tr key={p.id} className="hover:bg-stone-50 transition-colors">
                    <td className="px-6 py-4">
