          <p className="text-xs text-amber-400 font-bold tracking-widest mt-1 uppercase">Madeireira Pindorama</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'dashboard' ? 'bg-amber-600 shadow-md' : 'hover:bg-white/5'}`}>
            <LayoutDashboard size={20} /> Dashboard
          </button>

          <div className="pt-4 pb-2 px-4 text-xs font-bold text-white/40 uppercase tracking-widest">Estoque</div>
          <button onClick={() => setActiveTab('products')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'products' ? 'bg-amber-600 shadow-md' : 'hover:bg-white/5'}`}>
            <Package size={20} /> Produtos
          </button>
          <button onClick={() => setActiveTab('categories')} className={`w-full flex items-center gap-3 px-8 py-2 rounded-lg transition-colors text-sm ${activeTab === 'categories' ? 'text-amber-400 font-bold' : 'text-white/70 hover:text-white'}`}>
            <ChevronRight size={14} /> Categorias
          </button>
          <button onClick={() => setActiveTab('subcategories')} className={`w-full flex items-center gap-3 px-8 py-2 rounded-lg transition-colors text-sm ${activeTab === 'subcategories' ? 'text-amber-400 font-bold' : 'text-white/70 hover:text-white'}`}>
