                      </div>
                    ) : (
                      <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.subcategory || ''} onChange={(e) => setEditingProduct({...editingProduct, subcategory: e.target.value})}>
                        <option value="">Nenhuma</option>
                        {subcategories.filter(s => s.categoryId === editingProduct.category).map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                      </select>
                    )}
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Preço/Unidade</label>
                  <input type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.price || ''} onChange={(e) => setEditingProduct({...editingProduct, price: e.target.value})} />
                </div>

                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Foto do Produto</label>
                  <div className="flex items-center gap-4">
                    <div className="w-20 h-20 bg-stone-50 rounded-2xl border border-stone-200 overflow-hidden shrink-0 flex items-center justify-center">
                      {editingProduct.image ? <img src={editingProduct.image} className="w-full h-full object-cover" /> : <ImageIcon className="text-stone-300" />}
                    </div>
                    <input type="file" accept="image/*" className="hidden" id="prod-img-adm" onChange={(e) => handleImageUpload(e, (url) => setEditingProduct({...editingProduct, image: url}))} />
                    <label htmlFor="prod-img-adm" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold bg-white">
                      Upload da Foto
                    </label>
                  </div>
                </div>

                <div className="pt-4 flex gap-3 sticky bottom-0 bg-white pb-2">
                  <button type="button" onClick={() => setEditingProduct(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg">Salvar Produto</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modal Parceiro */}
        {editingPartner && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingPartner.id.startsWith('new-') ? 'Novo Parceiro' : 'Editar Parceiro'}</h3>
                <button onClick={() => setEditingPartner(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => { 
                e.preventDefault(); 
                const newList = editingPartner.id.startsWith('new-') ? [...partners, {...editingPartner, id: Date.now().toString()}] : partners.map(p => p.id === editingPartner.id ? editingPartner : p);
                onUpdatePartners(newList);
                setEditingPartner(null);
              }} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Marca</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black" value={editingPartner.name} onChange={(e) => setEditingPartner({...editingPartner, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Logo (Upload)</label>
                  <div className="flex items-center gap-4">
                    <div className="w-20 h-20 bg-stone-50 rounded-2xl border border-stone-200 flex items-center justify-center">
                      {editingPartner.logo ? <img src={editingPartner.logo} className="w-full h-full object-contain p-2" /> : <ImageIcon className="text-stone-300" />}
                    </div>
                    <input type="file" accept="image/*" className="hidden" id="partner-img-adm" onChange={(e) => handleImageUpload(e, (url) => setEditingPartner({...editingPartner, logo: url}))} />
                    <label htmlFor="partner-img-adm" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold bg-white">Upload da Logo</label>
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingPartner(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg">Salvar Marca</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState } from 'react';
import { LayoutDashboard, Package, MessageSquare, Settings, LogOut, Plus, Trash2, Edit2, TrendingUp, Users, Save, X, Image as ImageIcon, Briefcase, Instagram, Facebook, Tag, Code, ChevronRight, Layers } from 'lucide-react';
import { Product, Partner, SiteSettings, Category, Subcategory } from '../types';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  categories: Category[];
  setCategories: React.Dispatch<React.SetStateAction<Category[]>>;
  subcategories: Subcategory[];
  setSubcategories: React.Dispatch<React.SetStateAction<Subcategory[]>>;
  messages: any[];
  onDeleteMessage: (id: string) => void;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => void;
  banners: string[];
  onUpdateBanners: (banners: string[]) => void;
  partners: Partner[];
  onUpdatePartners: (partners: Partner[]) => void;
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, onDeleteProduct, onUpdateProduct, onAddProduct,
  categories, setCategories,
  subcategories, setSubcategories,
  messages, onDeleteMessage,
  settings, onUpdateSettings,
  banners, onUpdateBanners,
  partners, onUpdatePartners,
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [editingSubcategory, setEditingSubcategory] = useState<Subcategory | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(settings);

  const [showQuickAddCategory, setShowQuickAddCategory] = useState(false);
  const [showQuickAddSubcategory, setShowQuickAddSubcategory] = useState(false);
  const [newName, setNewName] = useState('');

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        callback(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      if (editingProduct.id.startsWith('new-')) {
        onAddProduct(editingProduct);
      } else {
        onUpdateProduct(editingProduct);
      }
      setEditingProduct(null);
    }
  };

  const handleQuickAddCategory = () => {
    if (!newName.trim()) return;
    const newCat = { id: Date.now().toString(), name: newName };
    setCategories([...categories, newCat]);
    if (editingProduct) setEditingProduct({ ...editingProduct, category: newCat.id });
    setNewName('');
    setShowQuickAddCategory(false);
  };

  const handleQuickAddSubcategory = () => {
    if (!newName.trim() || !editingProduct?.category) return;
    const newSub = { id: Date.now().toString(), name: newName, categoryId: editingProduct.category };
    setSubcategories([...subcategories, newSub]);
    if (editingProduct) setEditingProduct({ ...editingProduct, subcategory: newSub.name });
    setNewName('');
    setShowQuickAddSubcategory(false);
  };

  const handleDeleteBanner = (index: number) => {
    if (window.confirm('Tem certeza que deseja remover esta imagem do banner inicial?')) {
      const newBanners = [...banners];
      newBanners.splice(index, 1);
      onUpdateBanners(newBanners);
    }
  };

  const handleDeletePartner = (id: string) => {
    if (window.confirm('Tem certeza que deseja remover este parceiro/marca?')) {
      onUpdatePartners(partners.filter(p => p.id !== id));
    }
  };

  const stats = [
    { label: 'Total de Produtos', value: products.length, icon: <Package className="text-amber-600" /> },
    { label: 'Categorias', value: categories.length, icon: <Layers className="text-amber-600" /> },
    { label: 'Banners Ativos', value: banners.length, icon: <ImageIcon className="text-amber-600" /> },
    { label: 'Mensagens', value: messages.length, icon: <MessageSquare className="text-amber-600" /> },
  ];

  return (
