                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Categoria Pai</label>
                    <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.categoryId} onChange={(e) => setEditingSubcategory({...editingSubcategory, categoryId: e.target.value})}>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Subcategoria</label>
