                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingPartner(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50 transition-all">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg hover:bg-green-900 transition-all">Salvar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory } from './types';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [banners, setBanners] = useState<string[]>(HERO_IMAGES);
  const [partners, setPartners] = useState<Partner[]>(PARTNERS);
  const [categories, setCategories] = useState<Category[]>(CATEGORIES.filter(c => c.id !== 'all'));
  const [subcategories, setSubcategories] = useState<Subcategory[]>([
    { id: '1', name: 'Vigas', categoryId: 'telhado' },
    { id: '2', name: 'Pranchas', categoryId: 'decorativo' },
    { id: '3', name: 'Postes', categoryId: 'bruto' }
  ]);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'PINDORAMA',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const [messages, setMessages] = useState([
    { id: '1', name: 'João da Silva', content: 'Solicitação de orçamento para telhado colonial.', time: 'Há 15 minutos' },
    { id: '2', name: 'Maria Lúcia', content: 'Dúvida sobre entrega em cidades vizinhas.', time: 'Há 30 minutos' },
    { id: '3', name: 'Paulo Costa', content: 'Interesse em deck de Cumaru para piscina.', time: 'Há 1 hora' }
  ]);

  // Handlers robustos com Functional Updates
  const handleDeleteProduct = (id: string) => {
    if (window.confirm('Tem certeza absoluta que deseja excluir este produto?')) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleUpdateProduct = (updated: Product) => {
    setProducts(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  const handleAddProduct = (newProd: Product) => {
    setProducts(prev => [...prev, { ...newProd, id: Date.now().toString() }]);
  };

  const handleDeleteMessage = (id: string) => {
    if (window.confirm('Excluir esta mensagem permanentemente?')) {
      setMessages(prev => prev.filter(m => m.id !== id));
    }
  };

  const handleDeleteCategory = (id: string) => {
    if (window.confirm('Excluir esta categoria? Isso pode afetar produtos vinculados.')) {
      setCategories(prev => prev.filter(c => c.id !== id));
    }
  };

  const handleDeleteSubcategory = (id: string) => {
    if (window.confirm('Deseja excluir esta subcategoria?')) {
      setSubcategories(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleDeletePartner = (id: string) => {
    if (window.confirm('Deseja remover este parceiro?')) {
      setPartners(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleDeleteBanner = (index: number) => {
    if (window.confirm('Remover este banner?')) {
      setBanners(prev => prev.filter((_, i) => i !== index));
    }
  };

  if (isAdmin) {
    return (
      <AdminPanel 
        products={products}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        categories={categories}
        setCategories={setCategories}
        onDeleteCategory={handleDeleteCategory}
        subcategories={subcategories}
        setSubcategories={setSubcategories}
        onDeleteSubcategory={handleDeleteSubcategory}
        messages={messages}
        onDeleteMessage={handleDeleteMessage}
        settings={settings}
        onUpdateSettings={setSettings}
        banners={banners}
        onUpdateBanners={setBanners}
        onDeleteBanner={handleDeleteBanner}
        partners={partners}
        onUpdatePartners={setPartners}
        onDeletePartner={handleDeletePartner}
        onLogout={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} 
      />
      <main>
        <Hero images={banners} />
        <About />
        <Partners partners={partners} />
        <Products products={products} categories={categories} />
        <Testimonials />
      </main>
      <Footer settings={settings} />

      <a
        href={`https://wa.me/${settings.whatsapp}`}
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-8 right-8 z-40 bg-green-500 text-white p-4 rounded-full shadow-2xl hover:bg-green-600 transition-all hover:scale-110 flex items-center justify-center"
      >
        <svg viewBox="0 0 24 24" width="32" height="32" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" /></svg>
      </a>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { LayoutDashboard, Package, MessageSquare, Settings, LogOut, Plus, Trash2, Edit2, TrendingUp, Users, Save, X, Image as ImageIcon, Briefcase, Instagram, Facebook, Tag, Code, ChevronRight, Layers } from 'lucide-react';
import { Product, Partner, SiteSettings, Category, Subcategory } from '../types';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  categories: Category[];
  setCategories: React.Dispatch<React.SetStateAction<Category[]>>;
  onDeleteCategory: (id: string) => void;
  subcategories: Subcategory[];
  setSubcategories: React.Dispatch<React.SetStateAction<Subcategory[]>>;
  onDeleteSubcategory: (id: string) => void;
  messages: any[];
  onDeleteMessage: (id: string) => void;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => void;
  banners: string[];
  onUpdateBanners: (banners: string[]) => void;
  onDeleteBanner: (index: number) => void;
  partners: Partner[];
  onUpdatePartners: (partners: Partner[]) => void;
  onDeletePartner: (id: string) => void;
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, onDeleteProduct, onUpdateProduct, onAddProduct,
  categories, setCategories, onDeleteCategory,
  subcategories, setSubcategories, onDeleteSubcategory,
  messages, onDeleteMessage,
  settings, onUpdateSettings,
  banners, onUpdateBanners, onDeleteBanner,
  partners, onUpdatePartners, onDeletePartner,
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [editingSubcategory, setEditingSubcategory] = useState<Subcategory | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(settings);

  const [showQuickAddCategory, setShowQuickAddCategory] = useState(false);
  const [showQuickAddSubcategory, setShowQuickAddSubcategory] = useState(false);
  const [newName, setNewName] = useState('');

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        callback(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      if (editingProduct.id.startsWith('new-')) {
        onAddProduct(editingProduct);
      } else {
        onUpdateProduct(editingProduct);
      }
      setEditingProduct(null);
    }
  };

  const handleQuickAddCategory = () => {
    if (!newName.trim()) return;
    const newCat = { id: Date.now().toString(), name: newName };
    setCategories(prev => [...prev, newCat]);
    if (editingProduct) setEditingProduct({ ...editingProduct, category: newCat.id });
    setNewName('');
    setShowQuickAddCategory(false);
  };

  const handleQuickAddSubcategory = () => {
    if (!newName.trim() || !editingProduct?.category) return;
    const newSub = { id: Date.now().toString(), name: newName, categoryId: editingProduct.category };
    setSubcategories(prev => [...prev, newSub]);
    if (editingProduct) setEditingProduct({ ...editingProduct, subcategory: newSub.name });
    setNewName('');
    setShowQuickAddSubcategory(false);
  };

  const stats = [
    { label: 'Total de Produtos', value: products.length, icon: <Package className="text-amber-600" /> },
    { label: 'Categorias', value: categories.length, icon: <Layers className="text-amber-600" /> },
    { label: 'Banners Ativos', value: banners.length, icon: <ImageIcon className="text-amber-600" /> },
    { label: 'Mensagens', value: messages.length, icon: <MessageSquare className="text-amber-600" /> },
  ];

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-pindorama-green text-white flex flex-col shrink-0">
        <div className="p-8 border-b border-white/10">
          <h2 className="text-2xl font-bold tracking-tight uppercase">PAINEL ADM</h2>
          <p className="text-xs text-amber-400 font-bold tracking-widest mt-1 uppercase">Madeireira Pindorama</p>
