                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Subcategoria</label>
                    <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.name} onChange={(e) => setEditingSubcategory({...editingSubcategory, name: e.target.value})} />
