                </tr>
              </thead>
              <tbody className="divide-y divide-stone-100">
                {subcategories.map((s) => (
                  <tr key={s.id}>
                    <td className="px-6 py-4 font-bold text-black">{s.name}</td>
                    <td className="px-6 py-4 text-stone-500">{categories.find(c => c.id === s.categoryId)?.name}</td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button type="button" onClick={() => setEditingSubcategory(s)} className="p-2 text-stone-400 hover:text-amber-600 transition-colors"><Edit2 size={18} /></button>
                        <button type="button" onClick={() => triggerConfirm('Excluir Subcategoria', `Deseja remover a subcategoria "${s.name}"?`, () => onDeleteSubcategory(s.id))} className="p-2 text-stone-400 hover:text-red-500 transition-colors"><Trash2 size={18} /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'banners' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {banners.map((url, idx) => (
              <div key={idx} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-stone-200 group relative h-64">
                <img src={url} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                  <button type="button" onClick={() => triggerConfirm('Remover Banner', 'Tem certeza que deseja remover esta imagem do banner inicial?', () => onDeleteBanner(idx))} className="bg-red-500 text-white p-4 rounded-full hover:bg-red-600 shadow-xl transition-all active:scale-95">
                    <Trash2 size={28} />
                  </button>
                </div>
                <div className="absolute bottom-4 left-4 bg-white/90 px-3 py-1 rounded-full text-xs font-bold text-stone-500 shadow">Banner #{idx + 1}</div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'partners' && (
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
            {partners.map((p) => (
              <div key={p.id} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200 text-center relative group">
                <img src={p.logo} alt={p.name} className="h-16 w-auto object-contain mx-auto mb-4" />
                <p className="font-bold text-black text-sm uppercase">{p.name}</p>
                <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button type="button" onClick={() => setEditingPartner(p)} className="p-2 bg-white/80 backdrop-blur shadow-sm text-stone-400 hover:text-amber-600 rounded-lg"><Edit2 size={16} /></button>
                  <button type="button" onClick={() => triggerConfirm('Remover Parceiro', `Deseja remover a marca parceira "${p.name}"?`, () => onDeletePartner(p.id))} className="p-2 bg-white/80 backdrop-blur shadow-sm text-stone-400 hover:text-red-500 rounded-lg"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'messages' && (
          <div className="space-y-4">
            {messages.map((m) => (
              <div key={m.id} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200 flex justify-between items-center group">
                <div className="flex gap-4 items-center">
                  <div className="w-12 h-12 bg-amber-100 text-amber-800 rounded-full flex items-center justify-center font-bold text-xl">{m.name.charAt(0)}</div>
                  <div>
                    <h4 className="font-bold text-black text-lg">{m.name}</h4>
                    <p className="text-stone-500">{m.content}</p>
                    <span className="text-xs text-stone-400 font-bold tracking-widest mt-2 block uppercase">{m.time}</span>
                  </div>
                </div>
                <button 
                  type="button" 
                  onClick={() => triggerConfirm('Excluir Mensagem', `Deseja excluir a mensagem de ${m.name}?`, () => onDeleteMessage(m.id))} 
                  className="p-3 text-stone-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all active:scale-95"
                >
                  <Trash2 size={22} />
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Modal Confirmação Customizado (Substitui window.confirm) */}
        {confirmDialog?.isOpen && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-sm shadow-2xl overflow-hidden border border-stone-200 p-8 text-center animate-in zoom-in-95 duration-200">
              <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertTriangle size={40} />
              </div>
              <h3 className="text-2xl font-bold text-pindorama-green mb-2">{confirmDialog.title}</h3>
              <p className="text-stone-500 mb-8 leading-relaxed">{confirmDialog.message}</p>
              <div className="flex gap-3">
                <button 
                  type="button" 
                  onClick={() => setConfirmDialog(null)} 
                  className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="button" 
                  onClick={confirmDialog.onConfirm} 
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-bold shadow-lg hover:bg-red-700 transition-all active:scale-95"
                >
                  Confirmar
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Modal Produto */}
        {editingProduct && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-xl shadow-2xl overflow-hidden border border-stone-200 flex flex-col max-h-[90vh]">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white shrink-0">
                <h3 className="text-xl font-bold">{editingProduct.id.startsWith('new-') ? 'Novo Produto' : 'Editar Produto'}</h3>
                <button type="button" onClick={() => setEditingProduct(null)}><X size={24} /></button>
              </div>
              <form onSubmit={handleSaveProduct} className="p-8 space-y-5 overflow-y-auto">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome do Produto</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.name} onChange={(e) => setEditingProduct({...editingProduct, name: e.target.value})} />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1 relative">
                    <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Categoria</label>
                      <button type="button" onClick={() => setShowQuickAddCategory(!showQuickAddCategory)} className="p-1 bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200 transition-colors">
                        <Plus size={14} />
                      </button>
                    </div>
                    {showQuickAddCategory ? (
                      <div className="flex gap-2 animate-in fade-in slide-in-from-top-2">
                        <input type="text" autoFocus className="flex-1 px-3 py-2 text-sm border border-amber-500 rounded-lg outline-none" placeholder="Nome" value={newName} onChange={(e) => setNewName(e.target.value)} />
                        <button type="button" onClick={handleQuickAddCategory} className="bg-amber-600 text-white px-2 rounded-lg transition-all active:scale-95"><Save size={16} /></button>
