                    ) : (
                      <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.category} onChange={(e) => setEditingProduct({...editingProduct, category: e.target.value, subcategory: ''})}>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    )}
                  </div>

                  <div className="space-y-1 relative">
                    <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Subcategoria</label>
                      <button type="button" disabled={!editingProduct.category} onClick={() => setShowQuickAddSubcategory(!showQuickAddSubcategory)} className="p-1 bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200 disabled:opacity-30 transition-colors">
                        <Plus size={14} />
                      </button>
                    </div>
                    {showQuickAddSubcategory ? (
                      <div className="flex gap-2 animate-in fade-in slide-in-from-top-2">
                        <input type="text" autoFocus className="flex-1 px-3 py-2 text-sm border border-amber-500 rounded-lg outline-none" placeholder="Nome" value={newName} onChange={(e) => setNewName(e.target.value)} />
                        <button type="button" onClick={handleQuickAddSubcategory} className="bg-amber-600 text-white px-2 rounded-lg transition-all active:scale-95"><Save size={16} /></button>
                      </div>
                    ) : (
                      <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.subcategory || ''} onChange={(e) => setEditingProduct({...editingProduct, subcategory: e.target.value})}>
                        <option value="">Nenhuma</option>
                        {subcategories.filter(s => s.categoryId === editingProduct.category).map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                      </select>
                    )}
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Preço/Unidade</label>
                  <input type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.price || ''} onChange={(e) => setEditingProduct({...editingProduct, price: e.target.value})} />
                </div>

                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Imagem (Upload)</label>
                  <div className="flex items-center gap-4">
                    <div className="w-20 h-20 bg-stone-50 rounded-2xl border border-stone-200 overflow-hidden shrink-0 flex items-center justify-center">
                      {editingProduct.image ? <img src={editingProduct.image} className="w-full h-full object-cover" /> : <ImageIcon className="text-stone-300" />}
                    </div>
                    <input type="file" accept="image/*" className="hidden" id="prod-img-adm" onChange={(e) => handleImageUpload(e, (url) => setEditingProduct({...editingProduct, image: url}))} />
                    <label htmlFor="prod-img-adm" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold bg-white hover:text-amber-600 transition-all">
                      Clique para fazer upload
                    </label>
                  </div>
                </div>

                <div className="pt-4 flex gap-3 sticky bottom-0 bg-white pb-2 shadow-[0_-20px_20px_-20px_rgba(0,0,0,0.1)]">
                  <button type="button" onClick={() => setEditingProduct(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50 transition-all">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg hover:bg-green-900 transition-all active:scale-[0.98]">Salvar Produto</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modais de Edição Adicionais (Categorias, Subcategorias, Parceiros) mantidos conforme implementação anterior, mas agora confirmados pelo custom modal */}
        {editingCategory && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingCategory.id.startsWith('new-') ? 'Nova Categoria' : 'Editar Categoria'}</h3>
                <button type="button" onClick={() => setEditingCategory(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (editingCategory.id.startsWith('new-')) {
                  setCategories(prev => [...prev, { ...editingCategory, id: Date.now().toString() }]);
                } else {
                  setCategories(prev => prev.map(c => c.id === editingCategory.id ? editingCategory : c));
                }
                setEditingCategory(null);
              }} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Categoria</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingCategory.name} onChange={(e) => setEditingCategory({...editingCategory, name: e.target.value})} />
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingCategory(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg active:scale-95">Salvar</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {editingSubcategory && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingSubcategory.id.startsWith('new-') ? 'Nova Subcategoria' : 'Editar Subcategoria'}</h3>
                <button type="button" onClick={() => setEditingSubcategory(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (editingSubcategory.id.startsWith('new-')) {
                  setSubcategories(prev => [...prev, { ...editingSubcategory, id: Date.now().toString() }]);
                } else {
                  setSubcategories(prev => prev.map(s => s.id === editingSubcategory.id ? editingSubcategory : s));
                }
                setEditingSubcategory(null);
              }} className="p-8 space-y-6">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Categoria Pai</label>
                    <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.categoryId} onChange={(e) => setEditingSubcategory({...editingSubcategory, categoryId: e.target.value})}>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Subcategoria</label>
                    <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.name} onChange={(e) => setEditingSubcategory({...editingSubcategory, name: e.target.value})} />
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingSubcategory(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg active:scale-95">Salvar</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {editingPartner && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingPartner.id.startsWith('new-') ? 'Novo Parceiro' : 'Editar Parceiro'}</h3>
                <button type="button" onClick={() => setEditingPartner(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => { 
                e.preventDefault(); 
                if (editingPartner.id.startsWith('new-')) {
                  onUpdatePartners([...partners, { ...editingPartner, id: Date.now().toString() }]);
                } else {
                  onUpdatePartners(partners.map(p => p.id === editingPartner.id ? editingPartner : p));
                }
                setEditingPartner(null);
              }} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Marca</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingPartner.name} onChange={(e) => setEditingPartner({...editingPartner, name: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Logo (Upload)</label>
                  <div className="flex items-center gap-4">
                    <div className="w-20 h-20 bg-stone-50 rounded-2xl border border-stone-200 flex items-center justify-center overflow-hidden">
                      {editingPartner.logo ? <img src={editingPartner.logo} className="w-full h-full object-contain p-2" /> : <ImageIcon className="text-stone-300" />}
                    </div>
                    <input type="file" accept="image/*" className="hidden" id="partner-img-adm" onChange={(e) => handleImageUpload(e, (url) => setEditingPartner({...editingPartner, logo: url}))} />
                    <label htmlFor="partner-img-adm" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold bg-white transition-all">Upload da Logo</label>
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingPartner(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50 transition-all">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg hover:bg-green-900 transition-all active:scale-95">Salvar</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, MessageSquare, Settings, LogOut, Plus, Trash2, Edit2, TrendingUp, Users, Save, X, Image as ImageIcon, Briefcase, Instagram, Facebook, Tag, Code, ChevronRight, Layers, AlertTriangle, MapPin, Clock, Phone, Mail, Globe } from 'lucide-react';
import { Product, Partner, SiteSettings, Category, Subcategory } from '../types';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => void;
  onUpdateProduct: (product: Product) => void;
  onAddProduct: (product: Product) => void;
  categories: Category[];
  setCategories: React.Dispatch<React.SetStateAction<Category[]>>;
  onDeleteCategory: (id: string) => void;
  subcategories: Subcategory[];
  setSubcategories: React.Dispatch<React.SetStateAction<Subcategory[]>>;
  onDeleteSubcategory: (id: string) => void;
  messages: any[];
  onDeleteMessage: (id: string) => void;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => void;
  banners: string[];
  onUpdateBanners: (banners: string[]) => void;
  onDeleteBanner: (index: number) => void;
  partners: Partner[];
  onUpdatePartners: (partners: Partner[]) => void;
  onDeletePartner: (id: string) => void;
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, onDeleteProduct, onUpdateProduct, onAddProduct,
  categories, setCategories, onDeleteCategory,
  subcategories, setSubcategories, onDeleteSubcategory,
  messages, onDeleteMessage,
  settings, onUpdateSettings,
  banners, onUpdateBanners, onDeleteBanner,
  partners, onUpdatePartners, onDeletePartner,
  onLogout 
}) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [editingSubcategory, setEditingSubcategory] = useState<Subcategory | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(settings);

  // Custom Confirmation Modal State
  const [confirmDialog, setConfirmDialog] = useState<{ isOpen: boolean, title: string, message: string, onConfirm: () => void } | null>(null);

  const [showQuickAddCategory, setShowQuickAddCategory] = useState(false);
  const [showQuickAddSubcategory, setShowQuickAddSubcategory] = useState(false);
  const [newName, setNewName] = useState('');

  // Sincronizar localSettings se o prop settings mudar
  useEffect(() => {
    setLocalSettings(settings);
  }, [settings]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        callback(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      if (editingProduct.id.startsWith('new-')) {
        onAddProduct(editingProduct);
      } else {
        onUpdateProduct(editingProduct);
      }
      setEditingProduct(null);
    }
  };

  const handleQuickAddCategory = () => {
    if (!newName.trim()) return;
    const newCat = { id: Date.now().toString(), name: newName };
    setCategories(prev => [...prev, newCat]);
    if (editingProduct) setEditingProduct({ ...editingProduct, category: newCat.id });
    setNewName('');
    setShowQuickAddCategory(false);
  };

  const handleQuickAddSubcategory = () => {
    if (!newName.trim() || !editingProduct?.category) return;
    const newSub = { id: Date.now().toString(), name: newName, categoryId: editingProduct.category };
    setSubcategories(prev => [...prev, newSub]);
    if (editingProduct) setEditingProduct({ ...editingProduct, subcategory: newSub.name });
    setNewName('');
    setShowQuickAddSubcategory(false);
  };

  const triggerConfirm = (title: string, message: string, action: () => void) => {
    setConfirmDialog({
      isOpen: true,
      title,
      message,
      onConfirm: () => {
        action();
        setConfirmDialog(null);
      }
    });
  };

  const stats = [
    { label: 'Total de Produtos', value: products.length, icon: <Package className="text-amber-600" /> },
    { label: 'Categorias', value: categories.length, icon: <Layers className="text-amber-600" /> },
    { label: 'Banners Ativos', value: banners.length, icon: <ImageIcon className="text-amber-600" /> },
    { label: 'Mensagens', value: messages.length, icon: <MessageSquare className="text-amber-600" /> },
  ];

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-pindorama-green text-white flex flex-col shrink-0">
        <div className="p-8 border-b border-white/10">
          <h2 className="text-2xl font-bold tracking-tight uppercase">PAINEL ADM</h2>
          <p className="text-xs text-amber-400 font-bold tracking-widest mt-1 uppercase">Madeireira Pindorama</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
