                      <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingProduct.subcategory || ''} onChange={(e) => setEditingProduct({...editingProduct, subcategory: e.target.value})}>
