                    </div>
                    <input type="file" accept="image/*" className="hidden" id="prod-img-adm" onChange={(e) => handleImageUpload(e, (url) => setEditingProduct({...editingProduct, image: url}))} />
                    <label htmlFor="prod-img-adm" className="flex-1 border-2 border-dashed border-stone-200 p-4 rounded-xl text-center cursor-pointer hover:border-amber-500 text-stone-400 text-sm font-bold bg-white hover:text-amber-600 transition-all">
                      Clique para fazer upload
                    </label>
                  </div>
                </div>

                <div className="pt-4 flex gap-3 sticky bottom-0 bg-white pb-2 shadow-[0_-20px_20px_-20px_rgba(0,0,0,0.1)]">
                  <button type="button" onClick={() => setEditingProduct(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400 hover:bg-stone-50 transition-all">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg hover:bg-green-900 transition-all active:scale-[0.98]">Salvar Produto</button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Modal Categoria */}
        {editingCategory && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingCategory.id.startsWith('new-') ? 'Nova Categoria' : 'Editar Categoria'}</h3>
                <button type="button" onClick={() => setEditingCategory(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (editingCategory.id.startsWith('new-')) {
                  setCategories(prev => [...prev, { ...editingCategory, id: Date.now().toString() }]);
                } else {
                  setCategories(prev => prev.map(c => c.id === editingCategory.id ? editingCategory : c));
                }
                setEditingCategory(null);
              }} className="p-8 space-y-6">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Categoria</label>
                  <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingCategory.name} onChange={(e) => setEditingCategory({...editingCategory, name: e.target.value})} />
