        {/* Modal Subcategoria */}
        {editingSubcategory && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden border border-stone-200">
              <div className="p-6 border-b border-stone-100 flex justify-between items-center bg-pindorama-green text-white">
                <h3 className="text-xl font-bold">{editingSubcategory.id.startsWith('new-') ? 'Nova Subcategoria' : 'Editar Subcategoria'}</h3>
                <button type="button" onClick={() => setEditingSubcategory(null)}><X size={24} /></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                if (editingSubcategory.id.startsWith('new-')) {
                  setSubcategories(prev => [...prev, { ...editingSubcategory, id: Date.now().toString() }]);
                } else {
                  setSubcategories(prev => prev.map(s => s.id === editingSubcategory.id ? editingSubcategory : s));
                }
                setEditingSubcategory(null);
              }} className="p-8 space-y-6">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Categoria Pai</label>
                    <select className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.categoryId} onChange={(e) => setEditingSubcategory({...editingSubcategory, categoryId: e.target.value})}>
                      {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-stone-400 uppercase tracking-widest">Nome da Subcategoria</label>
                    <input required type="text" className="w-full px-4 py-3 rounded-xl border border-stone-200 bg-white text-black outline-none focus:ring-2 focus:ring-amber-500" value={editingSubcategory.name} onChange={(e) => setEditingSubcategory({...editingSubcategory, name: e.target.value})} />
                  </div>
                </div>
                <div className="pt-4 flex gap-3">
                  <button type="button" onClick={() => setEditingSubcategory(null)} className="flex-1 py-4 border border-stone-200 rounded-2xl font-bold text-stone-400">Cancelar</button>
                  <button type="submit" className="flex-1 py-4 bg-pindorama-green text-white rounded-2xl font-bold shadow-lg active:scale-95">Salvar</button>
                </div>
              </form>
            </div>
