import { getFirestore } from "firebase/firestore";

// SUBSTITUA PELAS SUAS CREDENCIAIS DO CONSOLE DO FIREBASE
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "pindorama-madeiras.firebaseapp.com",
  projectId: "pindorama-madeiras",
  storageBucket: "pindorama-madeiras.appspot.com",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory } from './types';

// Firebase
import { db } from './firebaseConfig';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  addDoc, 
  query, 
  orderBy 
} from "firebase/firestore";

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);

  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<string[]>([]);
  const [partners, setPartners] = useState<Partner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);
  const [messages, setMessages] = useState<any[]>([]);
  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'PINDORAMA',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  // Real-time Sync with Firebase
  useEffect(() => {
    const unsubProducts = onSnapshot(collection(db, "products"), (snapshot) => {
      const prods = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Product));
      setProducts(prods.length > 0 ? prods : PRODUCTS);
      setLoading(false);
    });

    const unsubSettings = onSnapshot(doc(db, "settings", "main"), (doc) => {
      if (doc.exists()) {
        setSettings(doc.data() as SiteSettings);
      }
    });

    const unsubBanners = onSnapshot(doc(db, "site_assets", "banners"), (doc) => {
      if (doc.exists()) {
        setBanners(doc.data().urls || HERO_IMAGES);
      } else {
        setBanners(HERO_IMAGES);
      }
    });

    const unsubPartners = onSnapshot(collection(db, "partners"), (snapshot) => {
      const parts = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Partner));
      setPartners(parts.length > 0 ? parts : PARTNERS);
    });

    const unsubCategories = onSnapshot(collection(db, "categories"), (snapshot) => {
      const cats = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Category));
      setCategories(cats.length > 0 ? cats : CATEGORIES.filter(c => c.id !== 'all'));
    });

    const unsubSubcategories = onSnapshot(collection(db, "subcategories"), (snapshot) => {
      const subs = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Subcategory));
      setSubcategories(subs);
    });

    const unsubMessages = onSnapshot(query(collection(db, "messages"), orderBy("timestamp", "desc")), (snapshot) => {
      const msgs = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
      setMessages(msgs);
    });

    return () => {
      unsubProducts();
      unsubSettings();
      unsubBanners();
      unsubPartners();
      unsubCategories();
      unsubSubcategories();
      unsubMessages();
    };
  }, []);

  // Handlers Persistentes no Firebase
  const handleAddProduct = async (newProd: Product) => {
    const { id, ...data } = newProd;
    await addDoc(collection(db, "products"), data);
  };

  const handleUpdateProduct = async (updated: Product) => {
    const { id, ...data } = updated;
    await updateDoc(doc(db, "products", id), data as any);
  };

  const handleDeleteProduct = async (id: string) => {
    await deleteDoc(doc(db, "products", id));
  };

  const handleUpdateSettings = async (newSettings: SiteSettings) => {
    await setDoc(doc(db, "settings", "main"), newSettings);
  };

  const handleUpdateBanners = async (newUrls: string[]) => {
    await setDoc(doc(db, "site_assets", "banners"), { urls: newUrls });
  };

  const handleDeleteBanner = async (index: number) => {
    const newBanners = banners.filter((_, i) => i !== index);
    await handleUpdateBanners(newBanners);
  };

  const handleDeleteMessage = async (id: string) => {
    await deleteDoc(doc(db, "messages", id));
  };

  const handleUpdatePartners = async (newPartners: Partner[]) => {
    // Para simplificar, parceiros são tratados como coleção, mas o painel envia o array completo em alguns casos
    // Aqui implementamos a lógica de sincronização individual se necessário
    setPartners(newPartners); 
  };

  const handleDeletePartner = async (id: string) => {
    await deleteDoc(doc(db, "partners", id));
  };

  const handleDeleteCategory = async (id: string) => {
    await deleteDoc(doc(db, "categories", id));
  };

  const handleDeleteSubcategory = async (id: string) => {
    await deleteDoc(doc(db, "subcategories", id));
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-pindorama-green text-white">
        <div className="w-16 h-16 border-4 border-amber-400 border-t-transparent rounded-full animate-spin mb-4"></div>
        <h2 className="text-xl font-bold tracking-widest uppercase animate-pulse">Madeireira Pindorama</h2>
        <p className="text-amber-400/60 text-sm mt-2">Sincronizando dados...</p>
      </div>
    );
  }

  if (isAdmin) {
    return (
      <AdminPanel 
        products={products}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        categories={categories}
        setCategories={async (val: any) => {
          // Lógica para lidar com setCategories do AdminPanel (que envia função ou valor)
          if (typeof val === 'function') {
            const next = val(categories);
            // Sincronizar apenas o novo
            const latest = next[next.length - 1];
            if (latest) await addDoc(collection(db, "categories"), latest);
          }
        }}
        onDeleteCategory={handleDeleteCategory}
        subcategories={subcategories}
        setSubcategories={async (val: any) => {
          if (typeof val === 'function') {
            const next = val(subcategories);
            const latest = next[next.length - 1];
            if (latest) await addDoc(collection(db, "subcategories"), latest);
          }
        }}
        onDeleteSubcategory={handleDeleteSubcategory}
        messages={messages}
        onDeleteMessage={handleDeleteMessage}
        settings={settings}
        onUpdateSettings={handleUpdateSettings}
        banners={banners}
        onUpdateBanners={handleUpdateBanners}
        onDeleteBanner={handleDeleteBanner}
        partners={partners}
        onUpdatePartners={async (val: any) => {
          if (Array.isArray(val)) {
             // Lógica de salvamento em lote se necessário
          }
        }}
        onDeletePartner={handleDeletePartner}
        onLogout={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} 
      />
      <main>
        <Hero images={banners} />
        <About />
        <Partners partners={partners} />
        <Products products={products} categories={categories} />
        <Testimonials />
      </main>
      <Footer settings={settings} />

      <a
        href={`https://wa.me/${settings.whatsapp}`}
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-8 right-8 z-40 bg-green-500 text-white p-4 rounded-full shadow-2xl hover:bg-green-600 transition-all hover:scale-110 flex items-center justify-center"
      >
        <svg viewBox="0 0 24 24" width="32" height="32" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" /></svg>
      </a>
    </div>
  );
};

export default App;

