    );

    const unsubMessages = onSnapshot(query(collection(db, "messages"), orderBy("timestamp", "desc")), 
      (snapshot) => {
        const msgs = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
        setMessages(msgs);
      },
      handleError
    );

    return () => {
      unsubProducts();
      unsubSettings();
      unsubBanners();
      unsubPartners();
      unsubCategories();
      unsubSubcategories();
      unsubMessages();
    };
