        const cats = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Category));
        if (cats.length > 0) setCategories(cats);
      },
      handleError
    );

    const unsubSubcategories = onSnapshot(collection(db, "subcategories"), 
      (snapshot) => {
        const subs = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Subcategory));
        setSubcategories(subs);
      },
      handleError
    );

    const unsubMessages = onSnapshot(query(collection(db, "messages"), orderBy("timestamp", "desc")), 
      (snapshot) => {
        const msgs = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
        setMessages(msgs);
      },
      handleError
    );

    return () => {
      unsubProducts();
      unsubSettings();
      unsubBanners();
      unsubPartners();
      unsubCategories();
      unsubSubcategories();
      unsubMessages();
    };
  }, []);

  // Handlers
  const handleAddProduct = async (newProd: Product) => {
    const { id, ...data } = newProd;
    await addDoc(collection(db, "products"), data);
  };

  const handleUpdateProduct = async (updated: Product) => {
    const { id, ...data } = updated;
    await updateDoc(doc(db, "products", id), data as any);
  };

  const handleDeleteProduct = async (id: string) => {
    await deleteDoc(doc(db, "products", id));
  };

  const handleUpdateSettings = async (newSettings: SiteSettings) => {
    await setDoc(doc(db, "settings", "main"), newSettings);
  };

  const handleUpdateBanners = async (newUrls: string[]) => {
    await setDoc(doc(db, "site_assets", "banners"), { urls: newUrls });
  };

  const handleDeleteBanner = async (index: number) => {
    const newBanners = banners.filter((_, i) => i !== index);
    await handleUpdateBanners(newBanners);
  };

  const handleDeleteMessage = async (id: string) => {
    await deleteDoc(doc(db, "messages", id));
  };

  const handleUpdatePartners = async (newPartnersList: Partner[]) => {
    // Logic for updating partners in Firebase
    console.log("Updating partners:", newPartnersList);
  };

  const handleDeletePartner = async (id: string) => {
    await deleteDoc(doc(db, "partners", id));
  };

  const handleDeleteCategory = async (id: string) => {
    await deleteDoc(doc(db, "categories", id));
  };

  const handleDeleteSubcategory = async (id: string) => {
    await deleteDoc(doc(db, "subcategories", id));
  };

  const handleAISend = async () => {
    if (!aiInput.trim()) return;
    const userText = aiInput;
    setAiInput('');
    setAiMessages(prev => [...prev, { role: 'user', text: userText }]);
    setIsTyping(true);

    try {
      // Fix: Create instance right before call as per guidelines
      const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

      // Fix: Ensure history starts with a 'user' message if multiple parts are sent
      // The greeting is a hardcoded model response, so we only include subsequent alternating history
      const history = aiMessages
        .filter((_, index) => index > 0) // Skip initial greeting to start history with 'user'
        .map(m => ({ role: m.role, parts: [{ text: m.text }] }));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: userText }] }],
        config: {
          systemInstruction: "Você é um consultor especialista da Madeireira Pindorama em Uberaba, MG. Sua missão é ajudar clientes a entenderem as melhores madeiras para seus projetos. Seja cordial, técnico e útil.",
        }
      });

      const aiText = response.text || "Desculpe, não consegui processar sua dúvida agora.";
      setAiMessages(prev => [...prev, { role: 'model', text: aiText }]);
    } catch (error) {
      console.error('Gemini AI Error:', error);
      setAiMessages(prev => [...prev, { role: 'model', text: "O assistente está ocupado no momento. Tente novamente em breve." }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-pindorama-green text-white">
        <div className="w-16 h-16 border-4 border-amber-400 border-t-transparent rounded-full animate-spin mb-4"></div>
        <h2 className="text-xl font-bold tracking-widest uppercase animate-pulse">Madeireira Pindorama</h2>
      </div>
    );
  }

  if (isAdmin) {
    return (
      <AdminPanel 
        products={products}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        categories={categories}
        setCategories={setCategories}
        onDeleteCategory={handleDeleteCategory}
        subcategories={subcategories}
        setSubcategories={setSubcategories}
        onDeleteSubcategory={handleDeleteSubcategory}
        messages={messages}
        onDeleteMessage={handleDeleteMessage}
        settings={settings}
        onUpdateSettings={handleUpdateSettings}
        banners={banners}
        onUpdateBanners={handleUpdateBanners}
        onDeleteBanner={handleDeleteBanner}
        partners={partners}
        onUpdatePartners={handleUpdatePartners}
        onDeletePartner={handleDeletePartner}
        onLogout={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} 
      />
      <main>
        <Hero images={banners} />
        <About />
        <Partners partners={partners} />
        <Products products={products} categories={categories} />
        <Testimonials />
      </main>
      <Footer settings={settings} />

      {/* Floating Buttons */}
      <div className="fixed bottom-8 right-8 z-40 flex flex-col gap-4">
        <button
          onClick={() => setIsAIChatOpen(!isAIChatOpen)}
          className="bg-amber-600 text-white p-4 rounded-full shadow-2xl hover:bg-amber-700 transition-all hover:scale-110 flex items-center justify-center group relative"
        >
          <Bot size={32} />
        </button>
        <a
          href={`https://wa.me/${settings.whatsapp}`}
          target="_blank"
          rel="noopener noreferrer"
          className="bg-green-500 text-white p-4 rounded-full shadow-2xl hover:bg-green-600 transition-all hover:scale-110 flex items-center justify-center"
        >
          <svg viewBox="0 0 24 24" width="32" height="32" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z" /></svg>
        </a>
      </div>

      {/* AI Chat Drawer */}
      {isAIChatOpen && (
        <div className="fixed bottom-24 right-8 z-50 w-[90vw] md:w-96 bg-white rounded-3xl shadow-2xl border border-stone-200 overflow-hidden flex flex-col animate-in slide-in-from-bottom-4 duration-300">
          <div className="bg-pindorama-green p-4 flex justify-between items-center text-white">
            <div className="flex items-center gap-3">
              <Bot size={20} className="text-amber-400" />
              <h4 className="font-bold text-sm">Consultor Especialista</h4>
            </div>
            <button onClick={() => setIsAIChatOpen(false)}><X size={20} /></button>
          </div>
          <div ref={scrollRef} className="h-80 overflow-y-auto p-4 space-y-4 bg-stone-50">
            {aiMessages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${m.role === 'user' ? 'bg-amber-600 text-white' : 'bg-white text-stone-700 shadow-sm'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl shadow-sm text-stone-400 text-xs italic animate-pulse">
                  Digitando...
                </div>
              </div>
            )}
          </div>
          <div className="p-4 bg-white border-t border-stone-100 flex gap-2">
            <input 
              type="text" 
              className="flex-1 bg-stone-100 rounded-xl px-4 py-2 text-sm outline-none" 
              value={aiInput} 
              onChange={(e) => setAiInput(e.target.value)} 
              onKeyDown={(e) => e.key === 'Enter' && handleAISend()} 
              placeholder="Digite sua dúvida..."
            />
            <button onClick={handleAISend} className="bg-pindorama-green text-white p-2 rounded-xl hover:bg-green-900 transition-colors"><Send size={20} /></button>
          </div>
        </div>
      )}
    </div>
  );
};

