  const handleUpdatePartner = async (p: Partner) => {
    const { id, ...data } = p;
    await updateDoc(doc(db, "partners", id), data as any);
  };
  const handleDeletePartner = async (id: string) => await deleteDoc(doc(db, "partners", id));

